    "Check drip emitters and soil moisture levels for optimal water delivery.": "ಉತ್ತಮ ನೀರಾವರಿಗಾಗಿ ಹನಿ ನೀರಾವರಿ ನಾಳಗಳು ಮತ್ತು ಮಣ್ಣಿನ ತೇವಾಂಶ ಮಟ್ಟವನ್ನು ಪರೀಕ್ಷಿಸಿ.",
    "Inspect sprinkler nozzles and schedule watering during early morning hours.": "ತುಂತುರು ನೀರಾವರಿ ನಳಿಕೆಗಳನ್ನು ಪರೀಕ್ಷಿಸಿ ಮತ್ತು ಮುಂಜಾನೆ ನೀರುಣಿಸುವ ವೇಳಾಪಟ್ಟಿ ಮಾಡಿ.",
    "Monitor weather forecasts and preserve soil moisture through mulching.": "ಹವಾಮಾನ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನಿಸಿ ಮತ್ತು ಹೊದಿಕೆ (ಮಲ್ಚಿಂಗ್) ಮೂಲಕ ಮಣ್ಣಿನ ತೇವಾಂಶ ಕಾಪಾಡಿ.",
    "Protect young seedling shoots from cutworms and maintain adequate weed control.": "ಎಳೆಯ ಸಸಿಗಳನ್ನು ಕೀಟಗಳಿಂದ ರಕ್ಷಿಸಿ ಮತ್ತು ಸೂಕ್ತ ಕಳೆ ನಿಯಂತ್ರಣ ನಿರ್ವಹಿಸಿ.",
    "Watch closely for sucking pests and flower drop symptoms.": "ರಸ ಹೀರುವ ಕೀಟಗಳು ಮತ್ತು ಹೂವು ಉದುರುವ ಲಕ್ಷಣಗಳನ್ನು ಎಚ್ಚರಿಕೆಯಿಂದ ಗಮನಿಸಿ.",
    "Inspect developing fruits for borer attacks and fungal spots.": "ಬೆಳೆಯುತ್ತಿರುವ ಕಾಯಿ/ಹಣ್ಣುಗಳಲ್ಲಿ ಕಾಯಿ ಕೊರಕ ಕೀಟಗಳು ಮತ್ತು ಶಿಲೀಂಧ್ರ ಚುಕ್ಕೆಗಳನ್ನು ಪರೀಕ್ಷಿಸಿ.",
    "Apply nitrogen-rich fertilizer to support vigorous leaf and stem development.": "ಎಲೆ ಮತ್ತು ಕಾಂಡದ ಉತ್ತಮ ಬೆಳವಣಿಗೆಗೆ ಸಾರಜನಕಯುಕ್ತ (ನೈಟ್ರೋಜನ್) ಗೊಬ್ಬರ ಹಾಕಿ.",
    "Boost phosphorus and potassium levels to promote strong root and flower development.": "ಬಲವಾದ ಬೇರು ಮತ್ತು ಹೂವಿನ ಬೆಳವಣಿಗೆಗೆ ಫಾಸ್ಫರಸ್ ಮತ್ತು ಪೊಟ್ಯಾಶಿಯಂ ಮಟ್ಟವನ್ನು ಹೆಚ್ಚಿಸಿ.",
    "Ensure potassium sufficiency to aid grain filling and fruit weight.": "ಕಾಳು ತುಂಬಲು ಮತ್ತು ಕಾಯಿ/ಹಣ್ಣಿನ ತೂಕ ಹೆಚ್ಚಿಸಲು ಪೊಟ್ಯಾಶಿಯಂ ಲಭ್ಯತೆಯನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.",
