    "Upload a crop image to identify possible diseases and get farming recommendations.": "சாத்தியமான நோய்களைக் கண்டறிந்து விவசாயப் பரிந்துரைகளைப் பெற பயிர் படத்தை பதிவேற்றவும்.",
    "Crop Image": "பயிர் படம்",
