    "How do I get personalized crop recommendations?": "मला वैयक्तिक पीक शिफारसी कशा मिळतील?",
    "Complete your Farm Profile with crop and location details to receive tailored advisory and weather alerts.": "योग्य सल्ला आणि हवामान इशारे मिळवण्यासाठी तुमच्या पिकाच्या आणि ठिकाणाच्या तपशीलांसह तुमची शेत प्रोफाईल पूर्ण करा.",
    "How do I change notification preferences?": "मी सूचना प्राधान्ये कशी बदलू?",
    "Go to Settings, scroll to Notification Preferences, and toggle weather, market, or crop advisory alerts.": "सेटिंग्जवर जा, सूचना प्राधान्यांवर स्क्रोल करा आणि हवामान, बाजार किंवा पीक सल्ला इशारे चालू/बंद करा.",
    "How do I change the application theme?": "मी ॲप्लिकेशन थीम कशी बदलू?",
    "In Settings under Themes, select Fresh Green, Sky Blue, Warm Earth, or Dark Night mode.": "थीम अंतर्गत सेटिंग्जमध्ये, ताजे हिरवे, आकाशी निळे, उबदार पृथ्वी किंवा डार्क नाईट मोड निवडा.",
    "How do I update my farm information?": "मी माझी शेताची माहिती कशी अपडेट करू?",
    "Navigate to My Farm or Profile page to update your crop type, farm area, soil type, and sowing dates.": "तुमचा पीक प्रकार, शेत क्षेत्र, मातीचा प्रकार आणि पेरणीच्या तारखा अपडेट करण्यासाठी माझे शेत किंवा प्रोफाईल पृष्ठावर जा.",
    "How do I change accessibility settings?": "मी सुलभता सेटिंग्ज कशी बदलू?",
    "In Settings under Accessibility Preferences, adjust font size, enable high contrast, or reduce motion.": "सुलभता प्राधान्यांमधील सेटिंग्जमध्ये, फॉन्ट आकार समायोजित करा, उच्च कॉन्ट्रास्ट सक्षम करा किंवा मोशन कमी करा.",
    "Manage crop and farming information.": "पीक आणि शेतीची माहिती व्यवस्थापित करा.",
    "Ask agricultural questions using text or voice.": "मजकूर किंवा आवाज वापरून कृषी प्रश्न विचारा.",
    "Upload a crop image to check possible diseases.": "संभाव्य रोगांची तपासणी करण्यासाठी पिकाची प्रतिमा अपलोड करा.",
    "Check current crop market prices.": "सध्याचे पीक बाजार भाव तपासा.",
    "View weather information for your location.": "तुमच्या ठिकाणासाठी हवामान माहिती पहा.",
    "Government Schemes": "शासकीय योजना",
    "Explore agricultural government schemes.": "कृषी शासकीय योजना जाणून घ्या.",
    "Microphone not working": "मायक्रोफोन काम करत नाही आहे",
    "Ensure your browser has permission to access the microphone. Check browser site settings and reload.": "तुमच्या ब्राउझरला मायक्रोफोन वापरण्याची अनुमती असल्याची खात्री करा. ब्राउझर साइट सेटिंग्ज तपासा आणि रिलोड करा.",
    "Language not changing": "भाषा बदलत नाही आहे",
    "Select your preferred language from the top navigation bar dropdown. The entire page will update instantly.": "वरच्या नेव्हिगेशन बार ड्रॉपडाऊनमधून तुमची पसंतीची भाषा निवडा. संपूर्ण पृष्ठ त्वरित अपडेट होईल.",
    "Voice response not working": "आवाज प्रतिसाद काम करत नाही आहे",
    "Verify that your device audio is unmuted and voice output settings are enabled in Language & Voice Preferences.": "तुमचे डिव्हाइस ऑडिओ अनम्यूट आहे आणि भाषा आणि आवाज प्राधान्यांमध्ये आवाज आउटपुट सेटिंग्ज सक्षम आहेत हे तपासा.",
    "Disease image not uploading": "रोगाची प्रतिमा अपलोड होत नाही आहे",
    "Make sure your image is in JPG, PNG, or WEBP format and smaller than 10 MB in size.": "तुमची प्रतिमा JPG, PNG किंवा WEBP फॉरमॅटमध्ये आहे आणि 10 MB पेक्षा लहान आहे याची खात्री करा.",
