    "Check drip emitters and soil moisture levels for optimal water delivery.": "योग्य सिंचनासाठी ठिबक सिंचन नोझल्स आणि मातीतील ओलावा तपासा.",
    "Inspect sprinkler nozzles and schedule watering during early morning hours.": "स्प्रिंकलर नोझल्सची पाहणी करा आणि पहाटे पाणी देण्याचे नियोजन करा.",
