    "Watch closely for sucking pests and flower drop symptoms.": "रस शोषणाऱ्या किडींवर आणि फूल गळतीच्या लक्षणांवर बारीक लक्ष ठेवा.",
    "Inspect developing fruits for borer attacks and fungal spots.": "वाढणाऱ्या फळांवर अळीचा प्रादुर्भाव आणि बुरशीजन्य डाग तपासा.",
    "Apply nitrogen-rich fertilizer to support vigorous leaf and stem development.": "पाने आणि खोडाच्या चांगल्या वाढीसाठी नत्रयुक्त खत द्या.",
    "Boost phosphorus and potassium levels to promote strong root and flower development.": "मुळांच्या आणि फुलांच्या वाढीसाठी स्फुरद आणि पालाशची मात्रा वाढवा.",
    "Ensure potassium sufficiency to aid grain filling and fruit weight.": "दाणे भरण्यासाठी आणि फळांच्या वजनासाठी पालाशची पर्याप्तता निश्चित करा.",
