    "Tell us about an issue you encountered while using AgriAdvisor.": "AgriAdvisor નો ઉપયોગ કરતી વખતે તમને પડેલી સમસ્યા વિશે અમને જણાવો.",
    "Rating": "રેટિંગ",
    "Privacy & Data Controls": "ગોપનીયતા અને ડેટા નિયંત્રણો",
    "Control your personal data, activity history, and personalization settings.": "તમારા અંગત ડેટા, પ્રવૃત્તિ ઇતિહાસ અને વ્યક્તિગત સેટિંગ્સને નિયંત્રિત કરો.",
    "Activity History": "પ્રવૃત્તિ ઇતિહાસ",
