    "Personalization Data": "વ્યક્તિગત ડેટા",
    "Use My Farm Data for Personalization": "વ્યક્તિગત ભલામણો માટે મારા ખેતરના ડેટાનો ઉપયોગ કરો",
    "Allow AgriAdvisor to use your farm profile to provide more relevant recommendations.": "વધુ સુસંગત ભલામણો આપવા માટે AgriAdvisor ને તમારા ખેતરની પ્રોફાઇલનો ઉપયોગ કરવાની મંજૂરી આપો.",
    "Chat History": "ચેટ ઇતિહાસ",
    "Manage your previous conversations with AgriAdvisor.": "AgriAdvisor સાથેની તમારી ભૂતકાળની વાતચીતનું સંચાલન કરો.",
    "Clear Chat History": "ચેટ ઇતિહાસ સાફ કરો",
