    "Danger Zone": "જોખમી વિસ્તાર",
    "Delete Account": "ખાતું કાઢી નાખો",
    "Permanently delete your AgriAdvisor account and associated data.": "તમારું AgriAdvisor ખાતું અને તેને સંબંધિત ડેટા કાયમ માટે કાઢી નાખો.",
    "Privacy Information": "ગોપનીયતા માહિતી",
    "Are you sure you want to clear your chat history?": "શું તમે ખરેખર તમારો ચેટ ઇતિહાસ સાફ કરવા માંગો છો?",
    "This will permanently remove your saved activity history. Do you want to continue?": "આનાથી તમારો સાચવેલ પ્રવૃત્તિ ઇતિહાસ કાયમ માટે દૂર થઈ જશે. શું તમે ચાલુ રાખવા માંગો છો?",
    "Delete Account?": "ખાતું કાઢી નાખવું છે?",
    "This action cannot be undone. Your account and associated data will be permanently deleted.": "આ ક્રિયા પાછી ખેંચી શકાતી નથી. તમારું ખાતું અને ડેટા કાયમ માટે કાઢી નાખવામાં આવશે.",
    "Chat history cleared successfully.": "ચેટ ઇતિહાસ સફળતાપૂર્વક સાફ કરવામાં આવ્યો.",
    "Activity history cleared successfully.": "પ્રવૃત્તિ ઇતિહાસ સફળતાપૂર્વક સાફ કરવામાં આવ્યો.",
    "Account deleted successfully.": "ખાતું સફળતાપૂર્વક કાઢી નાખવામાં આવ્યું.",
