    "How personalization uses farm information": "વ્યક્તિગતતા ખેતરની માહિતીનો ઉપયોગ કેવી રીતે કરે છે",
    "How users can clear their data": "વપરાશકર્તાઓ તેમનો ડેટા કેવી રીતે સાફ કરી શકે છે",
